-- 6-level cascade chain — used to test max_depth=5 enforcement.
-- Deleting from cg_l1 should reach cg_l5 exactly but NOT cg_l6.

CREATE TABLE IF NOT EXISTS cg_l1 (id SERIAL PRIMARY KEY, val TEXT);
CREATE TABLE IF NOT EXISTS cg_l2 (id SERIAL PRIMARY KEY, l1_id INT REFERENCES cg_l1(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cg_l3 (id SERIAL PRIMARY KEY, l2_id INT REFERENCES cg_l2(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cg_l4 (id SERIAL PRIMARY KEY, l3_id INT REFERENCES cg_l3(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cg_l5 (id SERIAL PRIMARY KEY, l4_id INT REFERENCES cg_l4(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cg_l6 (id SERIAL PRIMARY KEY, l5_id INT REFERENCES cg_l5(id) ON DELETE CASCADE);
